insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('riz au lait', 'Riz au lait', array['riz au lait maison']::text[], 'dish', $r$[{"title":"Riz au lait","intro":"Le riz au lait crémeux et vanillé de notre enfance.","minutes":45,"calories":320,"difficulty":"Facile","imageSearch":"rice pudding","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"riz rond","plural":"riz rond","qty":120,"unit":"g","have":false},{"name":"lait entier","plural":"lait entier","qty":1000,"unit":"ml","have":false},{"name":"sucre","plural":"sucre","qty":80,"unit":"g","have":false},{"name":"gousse de vanille","plural":"gousses de vanille","qty":1,"unit":"","have":false}],"steps":[{"text":"Rince le riz et fais-le blanchir 2 min dans l'eau bouillante.","timer":{"label":"Cuisson","min":2}},{"text":"Fais chauffer le lait avec la vanille fendue.","timer":null},{"text":"Ajoute le riz égoutté et cuis 35 min à feu doux en remuant souvent.","timer":{"label":"Cuisson","min":35}},{"text":"Ajoute le sucre à la fin et laisse tiédir.","timer":null}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Riz au lait de coco","intro":"Un riz au lait exotique, à la coco et à la mangue.","minutes":45,"calories":360,"difficulty":"Facile","imageSearch":"coconut rice pudding mango","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"riz rond","plural":"riz rond","qty":120,"unit":"g","have":false},{"name":"lait de coco","plural":"lait de coco","qty":40,"unit":"cl","have":false},{"name":"lait","plural":"laits","qty":60,"unit":"cl","have":false},{"name":"sucre","plural":"sucre","qty":60,"unit":"g","have":false},{"name":"mangue","plural":"mangues","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais chauffer le lait et le lait de coco.","timer":null},{"text":"Ajoute le riz rincé et cuis 35 min à feu doux en remuant.","timer":{"label":"Cuisson","min":35}},{"text":"Ajoute le sucre, laisse tiédir et sers avec la mangue en dés.","timer":null}],"dessert":true,"variant":"Au lait de coco","change":"Le lait de coco remplace une partie du lait."},{"title":"Riz au lait caramel","intro":"Le riz au lait, avec un caramel au beurre salé.","minutes":50,"calories":400,"difficulty":"Facile","imageSearch":"rice pudding salted caramel","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"riz rond","plural":"riz rond","qty":120,"unit":"g","have":false},{"name":"lait entier","plural":"lait entier","qty":1000,"unit":"ml","have":false},{"name":"sucre","plural":"sucre","qty":120,"unit":"g","have":false},{"name":"beurre demi-sel","plural":"beurre demi-sel","qty":30,"unit":"g","have":false},{"name":"crème fraîche liquide","plural":"crèmes fraîche liquide","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Fais cuire le riz dans le lait 35 min à feu doux avec 40 g de sucre.","timer":{"label":"Cuisson","min":35}},{"text":"Fais un caramel avec le reste du sucre, ajoute le beurre puis la crème.","timer":{"label":"Caramel","min":5}},{"text":"Sers le riz au lait nappé de caramel.","timer":null}],"kids":true,"dessert":true,"variant":"Au caramel","change":"Un caramel au beurre salé nappe le riz au lait."}]$r$::jsonb, 'claude')
