insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('saumon au four', 'Saumon au four', array['pave de saumon', 'saumon au four citron', 'filet de saumon']::text[], 'dish', $r$[{"title":"Pavés de saumon au four","intro":"Des pavés de saumon fondants, cuits au four avec citron, aneth et un filet d'huile d'olive.","minutes":25,"calories":420,"difficulty":"Facile","imageSearch":"baked salmon fillet lemon dill","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pavé de saumon","plural":"pavés de saumon","qty":4,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"aneth","plural":"aneth","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Pose les pavés dans un plat, côté peau en dessous.","timer":null},{"text":"Arrose d'huile, ajoute des rondelles de citron, l'aneth, sel et poivre.","timer":null},{"text":"Enfourne 15 min : le cœur doit rester légèrement nacré.","timer":{"label":"Four","min":15}}],"variant":"La classique","change":""},{"title":"Saumon au four en croûte de moutarde","intro":"Un saumon laqué moutarde-miel, sucré-salé.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"honey mustard salmon","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pavé de saumon","plural":"pavés de saumon","qty":4,"unit":"","have":false},{"name":"moutarde à l'ancienne","plural":"moutarde à l'ancienne","qty":2,"unit":"c. à s.","have":false},{"name":"miel","plural":"miel","qty":1,"unit":"c. à s.","have":false},{"name":"citron","plural":"citrons","qty":0.5,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Mélange la moutarde, le miel et le jus du citron.","timer":null},{"text":"Badigeonne les pavés, sale et poivre.","timer":null},{"text":"Enfourne 15 min.","timer":{"label":"Four","min":15}}],"variant":"Moutarde et miel","change":"Un glaçage moutarde et miel caramélise le dessus."},{"title":"Saumon au four et légumes","intro":"Le plat complet sur une plaque : saumon, brocoli et pommes de terre.","minutes":40,"calories":520,"difficulty":"Facile","imageSearch":"salmon traybake vegetables","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pavé de saumon","plural":"pavés de saumon","qty":4,"unit":"","have":false},{"name":"pomme de terre grenaille","plural":"pommes de terre grenaille","qty":600,"unit":"g","have":false},{"name":"brocoli","plural":"brocolis","qty":1,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Mets les pommes de terre coupées en deux sur une plaque avec 2 c. à s. d'huile, sel et paprika. Enfourne 20 min.","timer":{"label":"Four","min":20}},{"text":"Ajoute le brocoli en bouquets et les pavés de saumon arrosés d'huile et de citron.","timer":null},{"text":"Enfourne encore 15 min.","timer":{"label":"Four","min":15}}],"variant":"Tout en un","change":"Les légumes cuisent sur la même plaque que le saumon."}]$r$::jsonb, 'claude')
